Here’s a battle system object structure in C# for Unity, designed to fit your urban fantasy/cyberpunk setting with magic-tech hybrids and party-based turns:

```csharp
public class BattleManager : MonoBehaviour
{
    public List<Character> ActiveParty { get; private set; } = new List<Character>();
    public int TurnOrderIndex { get; private set; }
    public const int MAX_PARTY_SIZE = 4;

    public void StartBattle(List<Character> partyMembers)
    {
        ActiveParty = partyMembers;
        TurnOrderIndex = 0;
        ReorderTurnOrder();
    }

    private void ReorderTurnOrder()
    {
        ActiveParty.Sort((a, b) => b.Speed.CompareTo(a.Speed)); // Speed-based turn order
    }
}

public abstract class Character : MonoBehaviour
{
    public string Name { get; set; }
    public int Health { get; set; }
    public int MaxHealth { get; set; }
    public int Speed { get; set; } // Determines turn priority
    public List<Skill> Skills { get; set; } = new List<Skill>();
    public List<Item> Inventory { get; set; } = new List<Item>();

    public virtual void TakeDamage(int damage) 
    {
        Health -= damage;
        if (Health <= 0) Die();
    }

    public virtual void UseSkill(Skill skill)
    {
        if (skill.IsAvailable) 
        {
            skill.Activate(this);
            skill.Cooldown = skill.BaseCooldown;
        }
    }

    protected virtual void Die() { /* Handle death logic */ }
}

public class PlayerCharacter : Character
{
    public string BackgroundType { get; set; } // e.g., "Ex-Military", "Ex-Gang"
    public int CyberneticAugmentationLevel { get; set; } // From cyberpunk elements
}

public abstract class Skill
{
    public string Name { get; protected set; }
    public int BaseCooldown { get; protected set; }
    public int CurrentCooldown { get; protected set; }
    public bool IsAvailable => CurrentCooldown <= 0;

    public virtual void Activate(Character user) 
    {
        CurrentCooldown = BaseCooldown;
        // Actual skill logic (magic/cyber effects) handled here
    }
}

public class MagicSkill : Skill
{
    public int ManaCost { get; set; }
    public MagicType MagicType { get; set; } // e.g., "Arcane", "Cybernetic"

    public override void Activate(Character user)
    {
        base.Activate(user);
        user.Mana -= ManaCost; // Requires mana pool management
    }
}

public class Item
{
    public string Name { get; set; }
    public ItemType Type { get; set; }
    public int StackSize { get; set; } = 1;

    public void Use(Character user)
    {
        switch (Type)
        {
            case ItemType.Potion:
                user.Health = Mathf.Min(user.Health + 50, user.MaxHealth);
                break;
            case ItemType.Contraband:
                user.AddEffect(new CyberneticBoostEffect()); // Black market tech
                break;
        }
    }
}

public enum ItemType { Potion, Contraband, CraftingMaterial, Scroll }
public enum MagicType { Arcane, Cybernetic, Alchemical }
```

**Key features aligned with your vision:**  
- **Party members** with background-specific traits (e.g., `Ex-Military` gets tactical skills)  
- **Magic + cyberpunk fusion**: `MagicSkill` with mana costs vs. `Contraband` items giving cybernetic boosts  
- **Turn-based logic**: `BattleManager` handles speed-based turn ordering  
- **Economy integration**: `Contraband` items directly tie to your smuggling economy  
- **Character depth**: `PlayerCharacter` tracks cybernetic enhancements from your setting  

Want to refine any class (e.g., make `MagicSkill` use actual Unity effects, or add `Enemy` subclasses)?

